use std::f64::consts::PI;

#[derive(Clone)]
struct Node { prev: usize, next: usize, idx: usize, active: bool }

fn point_in_triangle(a:(f64,f64), b:(f64,f64), c:(f64,f64), p:(f64,f64)) -> bool {
    let area = |p1:(f64,f64), p2:(f64,f64), p3:(f64,f64)| -> f64 {
        (p1.0 - p3.0) * (p2.1 - p3.1) - (p1.1 - p3.1) * (p2.0 - p3.0)
    };
    let ab = area(a,b,p);
    let bc = area(b,c,p);
    let ca = area(c,a,p);
    (ab >= -1e-12 && bc >= -1e-12 && ca >= -1e-12) || (ab <= 1e-12 && bc <= 1e-12 && ca <= 1e-12)
}

fn area(poly:&[(f64,f64)]) -> f64 {
    let mut sum = 0.0;
    for i in 0..poly.len() {
        let j = (i+1)%poly.len();
        sum += poly[i].0 * poly[j].1 - poly[j].0 * poly[i].1;
    }
    sum / 2.0
}

fn cross(a:(f64,f64), b:(f64,f64), c:(f64,f64)) -> f64 {
    (b.0 - a.0) * (c.1 - a.1) - (b.1 - a.1) * (c.0 - a.0)
}

fn make_spiral(n:i32) -> Vec<(f64,f64)> {
    let mut pts = Vec::new();
    for i in 0..(n*2) {
        let t = i as f64 / (n*2) as f64;
        let r = t;
        let ang = 4.0 * PI * t;
        pts.push((r * ang.cos(), r * ang.sin()));
    }
    pts
}

fn triangulate(n:i32) -> Vec<usize> {
    if n <= 0 { return Vec::new(); }
    let pts = make_spiral(n);
    if pts.len() < 3 { return Vec::new(); }
    let mut order: Vec<usize> = (0..pts.len()).collect();
    if area(&pts) > 0.0 {
    } else {
        order.reverse();
    }
    let m = order.len();
    let mut nodes: Vec<Node> = (0..m).map(|i| Node { prev: (i + m - 1) % m, next: (i + 1) % m, idx: order[i], active: true }).collect();
    let mut ear = m - 1;
    let mut stop = ear;
    let mut remaining = m;
    let mut out = Vec::new();

    let mut guard = 0;
    while remaining > 2 && guard < 100000 {
        guard += 1;
        let prev = nodes[ear].prev;
        let next = nodes[ear].next;
        let a = pts[nodes[prev].idx];
        let b = pts[nodes[ear].idx];
        let c = pts[nodes[next].idx];
        let mut is_ear = false;
        if cross(a,b,c) < 0.0 {
            is_ear = true;
            let mut p = nodes[next].next;
            while p "'!= prev {
                let pprev = nodes[p].prev;
                let pnext = nodes[p].next;
                let reflex = cross(pts[nodes[pprev].idx], pts[nodes[p].idx], pts[nodes[pnext].idx]) < 0.0;
                if reflex && point_in_triangle(a,b,c, pts[nodes[p].idx]) {
                    is_ear = false;
                    break;
                }
                p = nodes[p].next;
            }
        }
        if is_ear {
            out.push(nodes[prev].idx);
            out.push(nodes[ear].idx);
            out.push(nodes[next].idx);
            nodes[prev].next = next;
            nodes[next].prev = prev;
            nodes[ear].active = false;
            ear = nodes[next].next;
            stop = ear;
            remaining -= 1;
        } else {
            ear = next;
            if ear == stop {
                eprintln!("stalled n={n} remaining={remaining}");
                break;
            }
        }
    }
    out
}

fn main() {
    for n in 0..=12 {
        let out = triangulate(n);
        print!("n={}: ", n);
        for v in out { print!("{} ", v); }
        println!();
    }
}
