use std::f64::consts::PI;

#[derive(Clone, Debug)]
struct Node {
    i: usize,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    removed: bool,
}

fn signed_area(data: &[(f64, f64)]) -> f64 {
    let mut sum = 0.0;
    let n = data.len();
    let mut j = n - 1;
    for i in 0..n {
        sum += (data[j].0 - data[i].0) * (data[i].1 + data[j].1);
        j = i;
    }
    sum
}

fn area(a: &Node, b: &Node, c: &Node) -> f64 {
    (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y)
}

fn equals(a: &Node, b: &Node) -> bool { a.x == b.x && a.y == b.y }

fn point_in_triangle(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64, px: f64, py: f64) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0 &&
    (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0 &&
    (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

fn remove_node(nodes: &mut [Node], p: usize) {
    let prev = nodes[p].prev;
    let next = nodes[p].next;
    nodes[prev].next = next;
    nodes[next].prev = prev;
    nodes[p].removed = true;
}

fn filter_points(nodes: &mut [Node], mut start: usize) -> Option<usize> {
    if nodes[start].removed { return None; }
    let mut p = start;
    loop {
        let next = nodes[p].next;
        if equals(&nodes[p], &nodes[next]) || area(&nodes[nodes[p].prev], &nodes[p], &nodes[next]) == 0.0 {
            if p == next { return None; }
            remove_node(nodes, p);
            p = nodes[next].prev;
