pub fn build_spiral_ring(n: i32) -> Vec<Point> {
    if n <= 0 {
        return Vec::new();
    }

    let Some(vertex_count) = n.checked_mul(2) else {
        return Vec::new();
    };

    let vertex_count = vertex_count as usize;
    let denominator = (n * 2) as f64;
    let mut spiral = Vec::with_capacity(vertex_count);

    for i in 0..vertex_count {
        let t = i as f64 / denominator;
        let radius = t;
        let angle = 4.0 * PI * t;
        spiral.push([radius * angle.cos(), radius * angle.sin()]);
    }

    spiral
}

