use crate::geometry::{point_in_triangle, triangle_area, Point};

pub fn triangulate_polygon(polygon: &[Vec<Point>]) -> Vec<u32> {
    polygon
        .first()
        .map_or_else(Vec::new, |ring| triangulate_ring(ring))
}

pub fn triangulate_ring(ring: &[Point]) -> Vec<u32> {
    let len = ring.len();
    if len < 3 {
        return Vec::new();
    }

    let mut prev = vec![0usize; len];
    let mut next = vec![0usize; len];

    for index in 0..len {
        prev[index] = if index == 0 { len - 1 } else { index - 1 };
        next[index] = if index + 1 == len { 0 } else { index + 1 };
    }

    let mut indices = Vec::with_capacity((len - 2) * 3);
    let mut ear = len - 1;
    let mut stop = ear;

    while prev[ear] != next[ear] {
        let previous = prev[ear];
        let following = next[ear];

        if is_ear(ear, ring, &prev, &next) {
            indices.push(previous as u32);
            indices.push(ear as u32);
            indices.push(following as u32);

            next[previous] = following;
            prev[following] = previous;

            ear = next[following];
            stop = ear;
            continue;
        }

        ear = following;
        if ear == stop {
            break;
        }
    }

    indices
}

fn is_ear(ear: usize, ring: &[Point], prev: &[usize], next: &[usize]) -> bool {
    let a = prev[ear];
    let b = ear;
    let c = next[ear];

    if triangle_area(&ring[a], &ring[b], &ring[c]) >= 0.0 {
        return false;
    }

    let mut point = next[c];
    while point != a {
        if point_in_triangle(&ring[a], &ring[b], &ring[c], &ring[point])
            && triangle_area(&ring[prev[point]], &ring[point], &ring[next[point]]) >= 0.0
        {
            return false;
        }

        point = next[point];
    }

    true
}

use super::geometry::{ring_signed_area, triangle_area, Point, Ring};

#[derive(Clone, Debug)]
pub struct Node {
    pub vertex_index: u32,
    pub point: Point,
    pub prev: usize,
    pub next: usize,
    pub removed: bool,
}

pub fn build_clockwise_ring(ring: &Ring) -> Option<(Vec<Node>, usize)> {
    if ring.is_empty() {
        return None;
    }

    let clockwise = true;
    let use_forward_order = clockwise == (ring_signed_area(ring) > 0.0);
    let indices: Vec<usize> = if use_forward_order {
        (0..ring.len()).collect()
    } else {
        (0..ring.len()).rev().collect()
    };

    let mut nodes = Vec::with_capacity(indices.len());
    for &index in &indices {
        nodes.push(Node {
            vertex_index: index as u32,
            point: ring[index],
            prev: 0,
            next: 0,
            removed: false,
        });
    }

    let node_count = nodes.len();
    for index in 0..node_count {
        nodes[index].prev = (index + node_count - 1) % node_count;
        nodes[index].next = (index + 1) % node_count;
    }

    Some((nodes, node_count - 1))
}

pub fn remove_node(nodes: &mut [Node], node_index: usize) {
    let prev = nodes[node_index].prev;
    let next = nodes[node_index].next;
    nodes[prev].next = next;
    nodes[next].prev = prev;
    nodes[node_index].removed = true;
}

pub fn filter_points(nodes: &mut [Node], start: usize) -> Option<usize> {
    if nodes[start].removed {
        return None;
    }

    let mut current = start;
    let mut stop = start;

    loop {
        let next = nodes[current].next;
        if same_point(nodes, current, next)
            || triangle_area_at(nodes, nodes[current].prev, current, next) == 0.0
        {
            if current == next {
                return None;
            }

            remove_node(nodes, current);
            current = nodes[next].prev;
            stop = current;

            if current == nodes[current].next {
                return None;
            }
        } else {
            current = next;
        }

        if current == stop {
            break;
        }
    }

    Some(stop)
}

pub fn same_point(nodes: &[Node], left: usize, right: usize) -> bool {
    nodes[left].point == nodes[right].point
}

pub fn triangle_area_at(nodes: &[Node], a: usize, b: usize, c: usize) -> f64 {
    triangle_area(nodes[a].point, nodes[b].point, nodes[c].point)
}
